import gzip
from io import BytesIO
from collections import OrderedDict
from random import randint
from time import strftime, gmtime
import datetime

import dateutil.tz

from taf.gnb.oam.ne3s.ws.components.base import FunctionalComponent
from taf.gnb.oam.ne3s.ws.components.ATL.v1.resources.templates import templates
from taf.gnb.oam.ne3s.ws.components.connection.exceptions import NE3SRequestFailed
from taf.gnb.oam.ne3s.ws.components.connection.ne3s_service import NE3SService
from taf.gnb.oam.ne3s.ws.components.ATL.v1.resources.notifications.messages import (
    ATLNotification, ATLNotificationGroup)
from taf.gnb.oam.ne3s.ws.components.exceptions import OperationFailed, OperationTimeout
from taf.gnb.oam.ne3s.ws.exceptions import StreamTimeoutError
import logging

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class ATLv1(FunctionalComponent):
    PROVISION_CID = 'cid:provisionContent123'
    DEFAULT_UPLOAD_CONFIGURATION_INTERVAL = 30
    STREAMS = []
    _connection = None
    SUPPORTED_NOTIFICATIONS = ATLNotificationGroup

    def __init__(self, connection):
        self._connection = connection

    def get_audit_trail_logs(
            self,
            adaptation_version,
            logs_age_in_seconds,
            timeout):
        start_date = self._get_start_date(logs_age_in_seconds)
        stream_name = "ATL.get_audit_trail_logs"

        try:
            atl_stream = self.add_new_msg_stream(
                stream_name=stream_name, msg_list=[ATLNotification])

            self._request_audit_trail_logs_upload(start_date, adaptation_version)

            atl = atl_stream.get(timeout=timeout)
            if atl.soap.attachment_properties.compression == 'gzip':
                return self._gzip_decompress(atl.attachment.content)
            return atl.attachment.content

        except NE3SRequestFailed as e:
            err_msg = "Could not get audit trail logs due to NE3S Request Failure with Error: {}".format(e)
            raise OperationFailed(err_msg)

        except StreamTimeoutError as e:
            err_msg = "Requested audit trail logs were not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def _get_start_date(self, logs_age_in_seconds):
        """ Agent handles date in the following format:
        YYYY-mm-ddTHH:MM:SS.ms+HH:MM where ms stands for milliseconds.
        Last +HH:MM stands for time zone offset. """
        now = datetime.datetime.now()
        start = now - datetime.timedelta(seconds=logs_age_in_seconds)

        start_date_str = start.strftime('%Y-%m-%dT%H:%M:%S.%f')
        # Truncate microseconds to milliseconds
        start_date_str = start_date_str[:-3]

        # Get time zone offset
        local_tz = dateutil.tz.tzlocal()
        local_offset = local_tz.utcoffset(datetime.datetime.now(local_tz))

        offset_in_seconds = local_offset.total_seconds()
        formatted_offset = strftime("%H:%M", gmtime(offset_in_seconds))

        sign = "+" if offset_in_seconds >= 0 else "-"
        signed_offset = "{}{}".format(sign, formatted_offset)

        start_date_str += signed_offset
        return start_date_str

    def _request_audit_trail_logs_upload(self, start_date, adaptation_version):
        url = self._connection.create_soap_service_url(NE3SService.BULK)
        upload_action = 'upload'

        upload_content = templates.get_file_content('upload.xml', 'r')

        upload_content = upload_content.format(
            manager_registration_key=self._connection.REGISTRATION_KEY,
            session_id=self._connection.session_id,
            manager_id=self._connection.connection_details.manager_id,
            operation_id=randint(1, 100000),
            start_date=start_date,
            adaptation_id=adaptation_version
        )

        log.debug("ATL request upload content {}".format(
            upload_content))

        cid_soap = '1234a@apache.org'
        header_soap = {'Content-ID': '<{}>'.format(cid_soap)}

        fields = OrderedDict()
        fields[cid_soap] = (cid_soap, upload_content,
                            'text/xml; charset=UTF-8', header_soap)

        upload_response = self._connection.send_multipart_soap_message(
            url, fields, upload_action)

        log.debug("ATL upload response: {}".format(upload_response))
        return upload_response

    @staticmethod
    def _gzip_decompress(data):
        file_handle = BytesIO(data)
        gzip_file_handle = gzip.GzipFile(fileobj=file_handle)
        decompressed_data = gzip_file_handle.read()
        return decompressed_data
